<?php $pageTitle=page_title('Manage '.$order['order_number']); $page='farmer-orders'; ?>
<div class="dashboard-head reveal"><div><a class="text-green" style="font-size:.8rem;font-weight:750" href="<?= e(url('farmer-orders')) ?>">← Back to orders</a><h1 style="margin-top:7px"><?= e($order['order_number']) ?></h1><p><?= status_pill($order['status']) ?> · <?= format_date($order['created_at'],'M j, Y · g:i A') ?></p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><?php if($order['status']==='placed'): ?><form method="post" action="<?= e(url('farmer-order-status')) ?>" data-confirm="Decline this order? The reserved stock will be released."><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="status" value="declined"><button class="btn btn-danger" type="submit">Decline</button></form><form method="post" action="<?= e(url('farmer-order-status')) ?>"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="status" value="accepted"><button class="btn" type="submit"><?= icon('check') ?> Accept order</button></form><?php elseif($order['status']==='accepted'): ?><form method="post" action="<?= e(url('farmer-order-status')) ?>"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="status" value="ready"><button class="btn" type="submit"><?= icon('package') ?> Mark ready</button></form><?php elseif($order['status']==='ready'): ?><form method="post" action="<?= e(url('farmer-order-status')) ?>"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="status" value="completed"><button class="btn" type="submit"><?= icon('check') ?> Complete pickup</button></form><?php endif; ?></div></div>
<div class="detail-grid"><div><div class="content-card card"><div class="content-head"><div><h2>Items to prepare</h2><p>Price and quantity are locked from the original order.</p></div><strong><?= money($order['subtotal_cents']/100) ?></strong></div><?php foreach($orderItems as $item): ?><div class="cart-row"><div class="table-product"><span class="table-thumb"><?php $img=product_image_url($item['image']); if($img): ?><img src="<?= e($img) ?>" alt=""><?php else: ?>🥬<?php endif; ?></span><div><strong><?= e($item['product_name']) ?></strong><br><small class="text-muted"><?= money($item['price_cents']/100) ?> / <?= e($item['unit']) ?></small></div></div><div><small class="text-muted">Quantity</small><br><strong><?= (int)$item['quantity'] ?></strong></div><div><small class="text-muted">Line total</small><br><strong><?= money($item['line_total_cents']/100) ?></strong></div><div></div></div><?php endforeach; ?><?php if($order['note']): ?><div class="alert alert-info mt-3"><?= icon('message') ?><span><strong>Customer note:</strong> <?= e($order['note']) ?></span></div><?php endif; ?></div><div class="content-card card mt-3"><div class="content-head"><div><h2>Status history</h2><p>Transparent updates for both sides.</p></div></div><div class="timeline"><?php foreach($orderEvents as $event): ?><div class="timeline-item"><strong><?= e(status_label($event['event_type'])) ?></strong><span><?= e($event['note']) ?> · <?= format_date($event['created_at'],'M j, g:i A') ?></span></div><?php endforeach; ?></div></div></div>
<aside><div class="card order-summary"><span class="eyebrow">Customer</span><h2><?= e($order['customer_name']) ?></h2><p class="text-muted" style="font-size:.85rem"><?= e($order['customer_phone']) ?><br><?= e($order['customer_email']) ?></p><div class="summary-line"><span>Pickup date</span><strong><?= format_date($order['pickup_date'],'D, M j') ?></strong></div><div class="summary-line"><span>Window</span><strong><?= e(date('g:i A',strtotime($order['start_time']))) ?> – <?= e(date('g:i A',strtotime($order['end_time']))) ?></strong></div><div class="summary-line"><span>Market</span><strong><?= e($order['market_name']) ?></strong></div><div class="summary-total"><span>Due at pickup</span><strong><?= money($order['subtotal_cents']/100) ?></strong></div></div><div class="card card-pad mt-3"><span class="eyebrow">Pickup contact</span><p class="text-muted" style="font-size:.84rem"><?= e($order['customer_address']) ?></p><p class="field-help">Customer details are shown only to fulfill this farmer order.</p></div></aside></div>
